// The login pages — self-contained, on-brand dark pages (inline CSS + the Aresium mark) so they
// pull no extra assets that would need to bypass the auth gate. Plain <form> POSTs, no JavaScript.
// Accounts are Empire accounts: signing up and password resets happen on the hub.
const EMPIRE = "https://www.ares-empire.de";
const MARK = "data:image/png;base64,";

const esc = (s: string) =>
  s.replace(/[<>&"']/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;", "'": "&#39;" }[c] as string));

function page(content: string): string {
  return `<!doctype html>
<html lang="en" data-theme="dark">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
<title>Aresium — Log in</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #f6f7fb;
    background:
      radial-gradient(60% 40% at 50% 24%, rgba(255,45,75,0.14), transparent 60%),
      radial-gradient(50% 50% at 50% 100%, rgba(46,139,255,0.06), transparent 60%),
      #08090c;
  }
  .card {
    width: min(92vw, 360px); padding: 34px 30px 30px; text-align: center;
    border: 1px solid rgba(255,255,255,0.08); border-radius: 20px;
    background: rgba(20,21,27,0.6); backdrop-filter: blur(20px) saturate(150%);
    -webkit-backdrop-filter: blur(20px) saturate(150%);
    box-shadow: 0 24px 70px rgba(0,0,0,0.5);
  }
  .mark { width: 92px; height: 92px; object-fit: contain; margin: 0 auto 14px; display: block; }
  h1 { margin: 0 0 4px; font-size: 22px; font-weight: 700; letter-spacing: -0.01em; }
  .sub { margin: 0 0 22px; font-size: 13.5px; color: #8b91a0; }
  form { display: flex; flex-direction: column; gap: 12px; }
  input {
    height: 46px; padding: 0 15px; font-size: 15px; color: #f6f7fb;
    border: 1px solid rgba(255,255,255,0.12); border-radius: 13px;
    background: rgba(255,255,255,0.04); outline: none; transition: border-color .18s, background .18s;
  }
  input::placeholder { color: #6b7080; }
  input:focus { border-color: rgba(255,45,75,0.6); background: rgba(255,255,255,0.06); }
  button, .button {
    display: flex; align-items: center; justify-content: center; text-decoration: none; width: 100%;
    height: 46px; font-size: 15px; font-weight: 650; color: #fff; cursor: pointer;
    border: none; border-radius: 13px;
    background: linear-gradient(180deg, #ff3b56, #e11030);
    box-shadow: 0 8px 24px rgba(225,16,48,0.32); transition: filter .18s, transform .06s;
  }
  button:hover, .button:hover { filter: brightness(1.06); }
  button:active, .button:active { transform: translateY(1px); }
  .err {
    margin: 0 0 14px; padding: 9px 12px; font-size: 13px; color: #ffd7dc;
    border-radius: 11px; background: rgba(225,16,48,0.16); border: 1px solid rgba(255,80,100,0.4);
  }
  .alt { margin: 16px 0 0; font-size: 13px; color: #8b91a0; }
  .alt a { color: #ff5c73; text-decoration: none; }
  .alt a:hover { text-decoration: underline; }
</style>
</head>
<body>
  <main class="card">
    <img class="mark" src="${MARK}" alt="Aresium" />
    <h1>Aresium</h1>
    ${content}
  </main>
</body>
</html>`;
}

const errHtml = (error: string) => (error ? `<p class="err">${esc(error)}</p>` : "");

export function loginUnavailablePage(): string {
  return page(`<p class="sub">Login service unavailable, try again in a minute.</p>`);
}

/** /login — the start screen: one button, plus a small sign-up link. */
export function welcomePage(error = ""): string {
  return page(`<p class="sub">Log in with your Ares Empire account</p>
    ${errHtml(error)}
    <a class="button" href="/login/email">Log in</a>
    <p class="alt">New account? <a href="${EMPIRE}/signup">Sign up</a></p>`);
}

/** /login/email — email + password. */
export function loginPage(error = "", email = ""): string {
  return page(`<p class="sub">Log in with your Ares Empire account</p>
    ${errHtml(error)}
    <form method="POST" action="/login">
      <input type="email" name="email" placeholder="Email" aria-label="Email" autocomplete="username" value="${esc(email)}" required ${email ? "" : "autofocus"} />
      <input type="password" name="password" placeholder="Password" aria-label="Password" autocomplete="current-password" required ${email ? "autofocus" : ""} />
      <button type="submit">Log in</button>
    </form>
    <p class="alt"><a href="${EMPIRE}/forgot">Forgot password?</a> · <a href="${EMPIRE}/signup">Sign up</a></p>`);
}
